  { auto _e = ENTITY_HANDLES(); if (_e) { _o->ENTITY_HANDLES.resize(_e->size()); for (::flatbuffers::uoffset_t _i = 0; _i < _e->size(); _i++) { _o->ENTITY_HANDLES[_i] = _e->Get(_i); } } else { _o->ENTITY_HANDLES.resize(0); } }
